D[1001]={"^Reduces the cooldown of Light's Hammer by (.-) sec%.\n\nCritical heals with Flash of Light, Holy Light or Holy Shock now has a (.-)%% chance to gain mana equal to (.-)%% of the base cost of the spell%.%s*$","Reduz a recarga de Martelo de Luz em {{1}} s.\n\nOs acertos críticos com Clarão de Luz, Luz Sagrada ou Choque Sagrado agora têm {{2}}% de chance de obter mana igual a {{3}}% do custo base do feitiço."}
D[2655]={"^|cFF66DDFFLevel 10 Passive|r\nAvoiding an attack now has a (.-)%% chance to grant you |cffffffffAngelic Presence|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nEvitar um ataque agora tem {{1}}% de chance de conceder |cffffffffPresença Angelical|r."}
D[3052]={"^Increases the dispel resistance of your Divine Illumination ability by (.-)%%%.%s*$","Aumenta a resistência a despejes de sua habilidade Iluminação Divina em {{1}}%."}
D[3438]={"^|cffffffffValkyrie Spear|r now makes you leap to your target and slow their movement speed by (.-)%% for (.-)%.%s*$","|cffffffffLança de Valkiria|r agora faz você saltar até o alvo e reduzir sua velocidade de movimento em {{1}}% durante {{2}}."}
D[3443]={"^Allows |cFFFFFFFFBurning Light|r to critically hit and stack 1 additional time%.%s*$","Permite que |cFFFFFFFFLuz Ardente|r golpeie criticamente acumule 1 vezes adicionalmente."}
