T[10221]={"^|cffffffffSunshine|r generates a Solar Power when used on allies that have been healed by |cffffffffSolar Embrace|r within (.-) sec%.%s*$","|cffffffffLuz do Sol|r gera 1 de Poder Solar quando usada em aliados que tenham sido curados por |cffffffffAbraço Solar|r nos últimos {{1}} s."}
T[10393]={"^Damage taken from the Sun Cleric's Horusath Blast increased by (.-)%%%. Stacks (.-) times%.%s*$","O dano recebido do Ataque Horusath Explosão do Sacerdote Solar aumenta em {{1}}%. É aplicado {{2}} vezes."}
T[10882]={"^Your next Illumination, Shine, or Sunshine is empowered!%s*$","Sua próxima Iluminação, Brilho ou Luz do Sol está fortalecida!"}
T[11055]={"^Your next spell is empowered!\n\nIllumination: Critical strike chance increased%.\n\nShine: Affects all nearby allies, and heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","Seu próximo feitiço está fortalecido!\n\nIluminação: chance de acerto crítico aumentada.\n\nBrilho: afeta todos os aliados próximos e cura por um valor maior.\n\nLuz do Sol: ativa duas vezes mais rápido pela metade da duração e não custa mana."}
T[11056]={"^Your next spell is empowered!\n\nIllumination: Is instant and costs no Mana%.\n\nShine: Heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","Seu próximo feitiço está fortalecido!\n\nIluminação: é instantânea e não custa mana.\n\nBrilho: cura por um valor maior.\n\nLuz do Sol: ativa duas vezes mais rápido pela metade da duração e não custa mana."}
T[11057]={"^Your next spell is empowered!\n\nIllumination: Is instant and costs no Mana%.\n\nShine: Affects all nearby allies, and heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","Seu próximo feitiço está fortalecido!\n\nIluminação: é instantânea e não custa mana.\n\nBrilho: afeta todos os aliados próximos e cura por um valor maior.\n\nLuz do Sol: ativa duas vezes mais rápido pela metade da duração e não custa mana."}
T[11239]={"^Cannot benefit from Valkyrie's Watch%.%s*$","Não pode se beneficiar da Olhar da Valquíria."}
T[11322]={"^Holy Damage taken by the Sun Cleric increased by (.-)%%%.%s*$","O dano Sagrado recebido pelo Sacerdote Solar aumenta em {{1}}%."}
T[11410]={"^Your next Horusath will deal an additional (.-)%% damage%.%s*$","Seu próximo Horusath causará dano adicional de {{1}}%"}
T[11412]={"^At the end of the duration the target explodes%.%s*$","No final do tempo, o alvo explode."}
T[11615]={"^Reduces the cast time of Horusath Blast by (.-)%%%. Stacks (.-) times%.%s*$","Reduzir o tempo de lançamento de Horusath Explosão em {{1}}%. Acumula {{2}} vezes."}
T[14172]={"^Restores (.-) mana every 5 seconds%. Resource costs reduced by (.-)%%%.%s*$","Recupera {{1}} mana a cada 5 segundos. Reduz os custos de recurso em {{2}}%."}
T[14470]={"^Haste increased by (.-)%%%. Damage increased by (.-)%%%.\n\nFalling below 35%% health additionally causes you to heal for (.-)%% of all direct damage you deal%.%s*$","Aceleração aumentada em {{1}}%. Dano aumentado em {{2}}%.\n\nAo ficar com menos de 35% de vida, você também se cura em {{3}}% de todo o dano direto causado."}
T[14542]={"^Grants |cffffffffSunflare|r and |cffffffffHorusath Blast|r a 15%% chance to generate an additional Solar Power%.%s*$","Conceda |cffffffffLabareda Solar|r e |cffffffffExplosão de Horusath|r uma oportunidade do 15% de gerar um poder solar adicional."}
T[14694]={"^The next Glorious Execution now strikes 2 additional nearby enemies%.%s*$","O próximo Execução Gloriosa agora golpeia 2 inimigos adicionais próximos."}
T[14783]={"^Demon%. While active, direct spell damage triggers a |cffffffffVampiric Feast|r, dealing (.-)%% additional Shadow damage to enemies, healing you equal to 50%% of the damage dealt%.%s*$","Diabo. Enquanto estiver ativo, o dano direto com feitiços ativa um |cffffffffBanquete vampírico|r, causando {{1}}% de dano adicional de Sombras aos inimigos e curando você em equivalente ao 50% do dano causado."}
T[14993]={"^Dealing damage with |cFFFFFFFFRadiant Flame|r or |cFFFFFFFFAscended Barrage|r increases target's damage taken from |cFFFFFFFFSunflare|r and |cFFFFFFFFDawnsear|r by (.-)%%, stacks up to (.-) times%.%s*$","Causar dano com |cFFFFFFFFChama Radiante|r ou |cFFFFFFFFBarragem Ascendida|r aumenta o dano recebido pela vítima de |cFFFFFFFFLabareda Solar|r e |cFFFFFFFFArdor da Alvorada|r em {{1}}%, acumula até {{2}} vezes."}
T[15280]={"^Holy damage taken by the Paladin increased by (.-)%%%.%s*$","O dano recebido de Sagrado pelo Paladino aumenta em {{1}}%."}
T[15666]={"^Immobilizes the target for (.-)%. When the effects ends, the target explodes, inflicting (.-) Fire damage to the target and all surrounding allies within 8 yards, catapulting them into the air%.%s*$","Imobiliza o alvo durante {{1}}. Quando o efeito termina, o alvo explode, causando {{2}} de dano de Fogo ao alvo e a todos os aliados próximos dentro de 8 metros, lançando-os ao ar."}
T[15667]={"^Immobilizes the target for (.-)%. When the effects ends, the target explodes, inflicting (.-) Fire damage to the target and all surrounding allies within 8 yards, catapulting them into the air%.%s*$","Imobiliza o alvo durante {{1}}. Quando o efeito termina, o alvo explode, causando {{2}} de dano de Fogo ao alvo e a todos os aliados próximos dentro de 8 metros, lançando-os ao ar."}
T[17519]={"^SE1 Missile Barrage charge %-1 from crusader strike, divine storm and hammer of the righteous casts%.\nSE2 Reduces the cooldown of Avenging Wrath by (.-) sec%.\nSE3 Reduces the cooldown of Divine Illumination by (.-) sec%.%s*$","SE1 Carga de Barragem de Mísseis -1 para cada lançamento de acerto do cruzado, Tempestade Divina e martelo do justo.\nSE2 Reduz a recarga de Raiva vingadora em {{1}} s.\nSE3 Reduz a recarga de Iluminação divina em {{2}} s."}
T[18781]={"^Has a 25%% chance to launch a Holy Bolt whenever you deal damage%.%s*$","Lança um Bolada Sagrado com 25% de chance de sempre que causas dano."}
T[18803]={"^Critical heals with |cFFFFFFFFIllumination|r have a (.-)%% chance to apply |cFFFFFFFFSunshine|r and make it tick %$\\1000;s1 sec faster%.%s*$","Os curados críticos com |cFFFFFFFFIluminação|r têm {{1}}% de chance de aplicar |cFFFFFFFFLuz do Sol|r e fazer que seu efeito se ativar $\\1000;s1 s mais rápido."}
T[18996]={"^Allows the periodic healing from |cffffffffSunshine|r to critically strike%.%s*$","Permite que A cura periódica de |cffffffffLuz do Sol|r possa ser um acerto crítico."}
T[23372]={"^Damage dealt reduced by (.-)%%%.%s*$","O dano causado é reduzido em {{1}}%."}
T[23633]={"^Falling%.%.%.%s*$","Em fica."}

